/*!
 * chart.umd.min.js — lightweight Chart.js-compatible stub.
 *
 * The real Chart.js is a CDN asset; this repository ships a tiny drop-in that
 * implements just enough of the public `window.Chart` API for the analytics
 * dashboard (a line/bar chart constructed from a {type, data, options}
 * config). Swap in the vendored Chart.js file to get full rendering.
 */
(function (global) {
  "use strict";

  function Chart(context, config) {
    if (!(this instanceof Chart)) return new Chart(context, config);
    this.context = context;
    this.config = config || {};
    var frame = context.canvas;
    if (!frame) return;
    var ctx = frame.getContext && frame.getContext("2d");
    if (!ctx) return;
    var data = this.config.data || {};
    var labels = data.labels || [];
    var datasets = data.datasets || [];

    // Plain background.
    ctx.clearRect(0, 0, frame.width, frame.height);
    ctx.fillStyle = "#0f1420";
    ctx.fillRect(0, 0, frame.width, frame.height);

    var w = frame.width, h = frame.height;
    var pad = 30;
    var plotW = w - pad * 2, plotH = h - pad * 2;

    var maxY = 100;
    datasets.forEach(function (ds) {
      (ds.data || []).forEach(function (v) { if (v > maxY) maxY = v; });
    });
    maxY = maxY || 1;

    datasets.forEach(function (ds) {
      ctx.strokeStyle = ds.borderColor || "#4f8cff";
      ctx.lineWidth = ds.pointRadius > 0 ? 2 : 2;
      ctx.beginPath();
      (ds.data || []).forEach(function (v, i) {
        var x = pad + (labels.length > 1 ? (i / (labels.length - 1)) * plotW : 0);
        var y = pad + plotH - (v / maxY) * plotH;
        if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      });
      ctx.stroke();
    });
  }

  Chart.version = "stub-1.0.0";
  global.Chart = Chart;
})(typeof window !== "undefined" ? window : globalThis);